desired = {"ranker": {"image": "ranker:1.4", "replicas": 6}, "embed": {"image": "embed:2.0", "replicas": 3}}
actual = {"ranker": {"image": "ranker:1.3", "replicas": 6}, "embed": {"image": "embed:2.0", "replicas": 1},
          "debug-pod": {"image": "busybox", "replicas": 1}}
def diff(desired, actual):
    plan = []
    for k, want in desired.items():
        have = actual.get(k)
        if have is None:
            plan.append(("만들기", k, want))
        elif have != want:
            plan.append(("고치기", k, {f: (have.get(f), v) for f, v in want.items() if have.get(f) != v}))
    for k in actual:
        if k not in desired:
            plan.append(("지우기", k, None))
    return plan
for step in diff(desired, actual):
    print(step)
# ('고치기', 'ranker', {'image': ('ranker:1.3', 'ranker:1.4')})
# ('고치기', 'embed', {'replicas': (1, 3)})
# ('지우기', 'debug-pod', None)

def run(gang):
    free = [8, 8]
    jobs = {"A": [4, 4, 4], "B": [4, 4, 4]}
    placed = {"A": [], "B": []}
    order = [("A", 0), ("B", 0), ("A", 1), ("B", 1), ("A", 2), ("B", 2)]
    if gang:
        for name, pods in jobs.items():
            if sum(pods) <= sum(free):
                for p in pods:
                    i = max(range(2), key=lambda k: free[k]); free[i] -= p; placed[name].append(i)
        order = []
    for name, w in order:
        i = max(range(2), key=lambda k: free[k])
        if free[i] >= jobs[name][w]:
            free[i] -= jobs[name][w]; placed[name].append(i)
    for name in jobs:
        ok = len(placed[name]) == len(jobs[name])
        print(f"  {name}: 워커 {len(placed[name])}/3 -> {'학습 시작' if ok else ('대기열에서 기다림' if not placed[name] else '나머지를 기다리며 GPU 만 붙잡음')}")
    stuck = sum(4 * len(placed[n]) for n in jobs if len(placed[n]) < 3)
    print(f"  빈 GPU {sum(free)}장, 붙잡혔지만 안 도는 GPU {stuck}장")
print("파드마다 따로:"); run(False)
print("전부 아니면 무:"); run(True)
# 파드마다 따로:
#   A: 워커 2/3 -> 나머지를 기다리며 GPU 만 붙잡음
#   B: 워커 2/3 -> 나머지를 기다리며 GPU 만 붙잡음
#   빈 GPU 0장, 붙잡혔지만 안 도는 GPU 16장
# 전부 아니면 무:
#   A: 워커 3/3 -> 학습 시작
#   B: 워커 0/3 -> 대기열에서 기다림
